package com.betterbanksearch;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("betterbanksearch")
public interface BetterBankSearchConfig extends Config
{
	@Range(min = 2, max = 10)
	@ConfigItem(
		keyName = "minQueryLength",
		name = "Minimum query length",
		description = "Minimum number of characters required for semantic search"
	)
	default int minQueryLength()
	{
		return 3;
	}
}

package com.betterbanksearch;

import com.google.inject.Provides;
import java.io.IOException;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.events.ScriptCallbackEvent;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.game.ItemVariationMapping;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

@Slf4j
@PluginDescriptor(
	name = "Better Bank Search",
	description = "Search your bank by item type, combat style, slot, and more",
	tags = {"bank", "search", "semantic", "items", "tags"}
)
public class BetterBankSearchPlugin extends Plugin
{
	private static final String BANK_SEARCH_FILTER = "bankSearchFilter";

	@Inject
	private Client client;

	@Inject
	private ItemManager itemManager;

	@Inject
	private BetterBankSearchConfig config;

	@Inject
	private TagDataLoader tagDataLoader;

	@Inject
	private ScheduledExecutorService executor;

	private volatile TagIndex tagIndex;
	private Future<?> loadTask;

	// Script callbacks run on the client thread, so these fields need no synchronization.
	private String cachedSearch;
	private int cachedMinQueryLength = -1;
	private ParsedQuery cachedQuery;

	@Override
	protected void startUp()
	{
		loadTask = executor.submit(() ->
		{
			try
			{
				tagIndex = tagDataLoader.load();
				log.debug("Loaded {} tagged items", tagIndex.itemCount());
			}
			catch (IOException | RuntimeException ex)
			{
				log.warn("Unable to load Better Bank Search tag data; semantic search is disabled", ex);
			}
		});
	}

	@Override
	protected void shutDown()
	{
		if (loadTask != null)
		{
			loadTask.cancel(true);
			loadTask = null;
		}
		tagIndex = null;
		cachedSearch = null;
		cachedMinQueryLength = -1;
		cachedQuery = null;
	}

	@Subscribe
	public void onScriptCallbackEvent(ScriptCallbackEvent event)
	{
		if (!BANK_SEARCH_FILTER.equals(event.getEventName()))
		{
			return;
		}

		TagIndex index = tagIndex;
		if (index == null || client.getIntStackSize() < 2 || client.getObjectStackSize() < 1)
		{
			return;
		}

		Object searchObject = client.getObjectStack()[client.getObjectStackSize() - 1];
		if (!(searchObject instanceof String))
		{
			return;
		}
		String search = ((String) searchObject).trim();
		if (search.isEmpty()
			|| search.regionMatches(true, 0, "tag:", 0, 4))
		{
			return;
		}

		ParsedQuery query = getCachedQuery(index, search, config.minQueryLength());
		if (query == null)
		{
			return;
		}

		int[] intStack = client.getIntStack();
		int itemId = intStack[client.getIntStackSize() - 1];
		int canonicalId = itemManager.canonicalize(itemId);
		int variationBaseId = ItemVariationMapping.map(canonicalId);
		ItemStats stats = null;
		if (query.hasStatRequirements())
		{
			stats = itemManager.getItemStats(canonicalId);
			if (stats == null && variationBaseId != canonicalId)
			{
				stats = itemManager.getItemStats(variationBaseId);
			}
		}

		boolean matches = index.matches(canonicalId, query, stats);
		if (!matches)
		{
			matches = variationBaseId != canonicalId
				&& index.matches(variationBaseId, query, stats);
		}
		if (matches)
		{
			// The callback is additive-only: never overwrite another search provider's match with 0.
			intStack[client.getIntStackSize() - 2] = 1;
		}
	}

	ParsedQuery getCachedQuery(TagIndex index, String search, int minQueryLength)
	{
		if (!search.equals(cachedSearch) || minQueryLength != cachedMinQueryLength)
		{
			cachedSearch = search;
			cachedMinQueryLength = minQueryLength;
			cachedQuery = parseSearch(index, search, minQueryLength);
		}
		return cachedQuery;
	}

	static ParsedQuery parseSearch(TagIndex index, String search, int minQueryLength)
	{
		if (search == null)
		{
			return null;
		}

		String semanticSearch = search.trim();
		if (semanticSearch.isEmpty()
			|| semanticSearch.regionMatches(true, 0, "tag:", 0, 4))
		{
			return null;
		}

		boolean prefixed = false;
		if (semanticSearch.regionMatches(true, 0, "sem:", 0, 4))
		{
			semanticSearch = semanticSearch.substring(4).trim();
			prefixed = true;
		}
		else if (semanticSearch.regionMatches(true, 0, "s:", 0, 2))
		{
			semanticSearch = semanticSearch.substring(2).trim();
			prefixed = true;
		}

		boolean statPrefixed = semanticSearch.regionMatches(true, 0, "stat:", 0, 5);
		if (!prefixed && !statPrefixed && semanticSearch.length() < minQueryLength)
		{
			return null;
		}
		return new QueryMatcher(index).parse(semanticSearch, prefixed);
	}

	@Provides
	BetterBankSearchConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(BetterBankSearchConfig.class);
	}
}

package com.betterbanksearch;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.function.ToDoubleFunction;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemStats;

enum ItemStat
{
	ATTACK_STAB(equipment(ItemEquipmentStats::getAstab),
		"attack-stab", "astab", "stab", "stab-attack"),
	ATTACK_SLASH(equipment(ItemEquipmentStats::getAslash),
		"attack-slash", "aslash", "slash", "slash-attack"),
	ATTACK_CRUSH(equipment(ItemEquipmentStats::getAcrush),
		"attack-crush", "acrush", "crush", "crush-attack"),
	ATTACK_MAGIC(equipment(ItemEquipmentStats::getAmagic),
		"attack-magic", "amagic", "magic", "mage", "magic-attack", "mage-attack"),
	ATTACK_RANGED(equipment(ItemEquipmentStats::getArange),
		"attack-ranged", "arange", "range", "ranged", "range-attack", "ranged-attack"),

	DEFENCE_STAB(equipment(ItemEquipmentStats::getDstab),
		"defence-stab", "dstab", "defense-stab", "stab-defence", "stab-defense"),
	DEFENCE_SLASH(equipment(ItemEquipmentStats::getDslash),
		"defence-slash", "dslash", "defense-slash", "slash-defence", "slash-defense"),
	DEFENCE_CRUSH(equipment(ItemEquipmentStats::getDcrush),
		"defence-crush", "dcrush", "defense-crush", "crush-defence", "crush-defense"),
	DEFENCE_MAGIC(equipment(ItemEquipmentStats::getDmagic),
		"defence-magic", "dmagic", "defense-magic", "magic-defence", "magic-defense", "mage-defence", "mage-defense"),
	DEFENCE_RANGED(equipment(ItemEquipmentStats::getDrange),
		"defence-ranged", "drange", "defense-ranged", "defence-range", "defense-range", "range-defence", "range-defense", "ranged-defence", "ranged-defense"),

	MELEE_STRENGTH(equipment(ItemEquipmentStats::getStr),
		"strength", "str", "melee-strength"),
	RANGED_STRENGTH(equipment(ItemEquipmentStats::getRstr),
		"ranged-strength", "rstr", "range-strength"),
	MAGIC_DAMAGE(equipment(ItemEquipmentStats::getMdmg),
		"magic-damage", "mdmg", "mage-damage"),
	PRAYER(equipment(ItemEquipmentStats::getPrayer),
		"prayer", "pray"),
	ATTACK_SPEED(equipment(ItemEquipmentStats::getAspeed),
		"attack-speed", "aspeed", "speed", "weapon-speed"),
	WEIGHT(stats -> stats.getWeight(),
		"weight", "kg"),
	GE_LIMIT(stats -> (double) stats.getGeLimit(),
		"ge-limit", "gelimit", "buy-limit");

	private static final Map<String, ItemStat> LOOKUP = buildLookup();

	private final StatValue value;
	private final String[] names;

	ItemStat(StatValue value, String... names)
	{
		this.value = value;
		this.names = names;
	}

	Double read(ItemStats stats)
	{
		return stats == null ? null : value.read(stats);
	}

	static ItemStat find(String name)
	{
		if (name == null)
		{
			return null;
		}
		return LOOKUP.get(name.toLowerCase(Locale.ROOT).replace('_', '-'));
	}

	static Set<ItemStat> findByPrefix(String name)
	{
		String prefix = name.toLowerCase(Locale.ROOT).replace('_', '-');
		Set<ItemStat> matches = new LinkedHashSet<>();
		for (ItemStat stat : values())
		{
			for (String candidate : stat.names)
			{
				if (candidate.startsWith(prefix))
				{
					matches.add(stat);
					break;
				}
			}
		}
		return matches;
	}

	private static StatValue equipment(ToDoubleFunction<ItemEquipmentStats> value)
	{
		return stats ->
		{
			ItemEquipmentStats equipment = stats.getEquipment();
			return equipment == null ? null : value.applyAsDouble(equipment);
		};
	}

	private static Map<String, ItemStat> buildLookup()
	{
		Map<String, ItemStat> lookup = new HashMap<>();
		for (ItemStat stat : values())
		{
			for (String name : stat.names)
			{
				ItemStat previous = lookup.put(name, stat);
				if (previous != null)
				{
					throw new IllegalStateException("Duplicate item stat alias: " + name);
				}
			}
		}
		return Collections.unmodifiableMap(lookup);
	}

	@FunctionalInterface
	private interface StatValue
	{
		Double read(ItemStats stats);
	}
}

package com.betterbanksearch;

import java.util.Arrays;
import java.util.List;
import net.runelite.client.game.ItemStats;

public final class ParsedQuery
{
	private final long[][] requirementGroups;
	private final StatRequirementGroup[] statRequirements;

	ParsedQuery(List<long[]> requirementGroups, List<StatRequirementGroup> statRequirements)
	{
		this.requirementGroups = new long[requirementGroups.size()][2];
		for (int i = 0; i < requirementGroups.size(); i++)
		{
			this.requirementGroups[i] = requirementGroups.get(i).clone();
		}
		this.statRequirements = statRequirements.toArray(new StatRequirementGroup[0]);
	}

	public boolean isSatisfiedBy(long[] closure, ItemStats stats)
	{
		if (requirementGroups.length > 0 && closure == null)
		{
			return false;
		}
		for (long[] group : requirementGroups)
		{
			if (((closure[0] & group[0]) | (closure[1] & group[1])) == 0)
			{
				return false;
			}
		}
		for (StatRequirementGroup requirement : statRequirements)
		{
			if (!requirement.isSatisfiedBy(stats))
			{
				return false;
			}
		}
		return true;
	}

	boolean hasStatRequirements()
	{
		return statRequirements.length > 0;
	}

	int requiredTagCount()
	{
		return requirementGroups.length;
	}

	int requiredStatCount()
	{
		return statRequirements.length;
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof ParsedQuery))
		{
			return false;
		}
		ParsedQuery that = (ParsedQuery) other;
		return Arrays.deepEquals(requirementGroups, that.requirementGroups)
			&& Arrays.equals(statRequirements, that.statRequirements);
	}

	@Override
	public int hashCode()
	{
		return 31 * Arrays.deepHashCode(requirementGroups) + Arrays.hashCode(statRequirements);
	}
}

package com.betterbanksearch;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;

public final class QueryMatcher
{
	private static final int MAX_PHRASE_TOKENS = 3;

	private final TagIndex index;

	public QueryMatcher(TagIndex index)
	{
		this.index = index;
	}

	public ParsedQuery parse(String search)
	{
		return parse(search, false);
	}

	public ParsedQuery parse(String search, boolean allowTrailingPrefix)
	{
		if (search == null || search.trim().isEmpty())
		{
			return null;
		}

		String[] splitTokens = search.trim().split("\\s+");
		List<String> compactTokens = new ArrayList<>();
		for (int i = 0; i < splitTokens.length; i++)
		{
			if ("stat:".equalsIgnoreCase(splitTokens[i]) && i + 1 < splitTokens.length)
			{
				compactTokens.add("stat:" + splitTokens[++i]);
			}
			else
			{
				compactTokens.add(splitTokens[i]);
			}
		}

		String[] rawTokens = compactTokens.toArray(new String[0]);
		String[] tokens = new String[rawTokens.length];
		StatRequirementGroup[] parsedStats = new StatRequirementGroup[rawTokens.length];
		List<StatRequirementGroup> statRequirements = new ArrayList<>();
		for (int i = 0; i < rawTokens.length; i++)
		{
			String normalizedToken = index.normalizeToken(rawTokens[i]);
			boolean explicitStat = startsWithStatPrefix(rawTokens[i]);
			boolean allowBareStat = explicitStat || index.findTag(normalizedToken) == null;
			StatRequirementGroup stat = StatRequirement.parse(
				rawTokens[i], allowBareStat, explicitStat);
			if (stat != null)
			{
				parsedStats[i] = stat;
				statRequirements.add(stat);
			}
			else
			{
				if (explicitStat)
				{
					return null;
				}
				tokens[i] = normalizedToken;
			}
		}

		List<long[]> requirementGroups = new ArrayList<>();
		for (int position = 0; position < tokens.length;)
		{
			if (parsedStats[position] != null)
			{
				position++;
				continue;
			}

			Integer matchedTag = null;
			int matchedLength = 0;
			int trailingLength = 0;
			while (position + trailingLength < tokens.length
				&& parsedStats[position + trailingLength] == null)
			{
				trailingLength++;
			}
			int maximumLength = Math.min(MAX_PHRASE_TOKENS, trailingLength);
			for (int phraseLength = maximumLength; phraseLength >= 1; phraseLength--)
			{
				String phrase = join(tokens, position, phraseLength);
				matchedTag = index.findTag(phrase);
				if (matchedTag != null)
				{
					matchedLength = phraseLength;
					break;
				}
			}

			// Before committing to a shorter exact tag, try the complete remaining
			// phrase as an autocomplete prefix. For example, "teleport jew" should
			// resolve "teleport jewellery", not consume "teleport" on its own.
			if (allowTrailingPrefix
				&& position + trailingLength == tokens.length
				&& trailingLength <= MAX_PHRASE_TOKENS
				&& matchedLength < trailingLength)
			{
				Set<Integer> prefixMatches = index.findTagsByPrefix(
					join(tokens, position, trailingLength));
				if (!prefixMatches.isEmpty())
				{
					long[] group = new long[2];
					for (int tag : prefixMatches)
					{
						group[tag >>> 6] |= 1L << (tag & 63);
					}
					addDistinct(requirementGroups, group);
					position += trailingLength;
					continue;
				}
			}

			if (matchedTag == null)
			{
				return null;
			}

			long[] group = new long[2];
			group[matchedTag >>> 6] = 1L << (matchedTag & 63);
			addDistinct(requirementGroups, group);
			position += matchedLength;
		}

		return new ParsedQuery(requirementGroups, statRequirements);
	}

	private static boolean startsWithStatPrefix(String token)
	{
		return token.regionMatches(true, 0, "stat:", 0, 5);
	}

	private static void addDistinct(List<long[]> requirementGroups, long[] group)
	{
		for (long[] existing : requirementGroups)
		{
			if (Arrays.equals(existing, group))
			{
				return;
			}
		}
		requirementGroups.add(group);
	}

	private static String join(String[] tokens, int start, int length)
	{
		StringBuilder phrase = new StringBuilder(tokens[start]);
		for (int i = 1; i < length; i++)
		{
			phrase.append(' ').append(tokens[start + i]);
		}
		return phrase.toString();
	}
}

package com.betterbanksearch;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.client.game.ItemStats;

final class StatRequirement
{
	private static final Pattern CLAUSE = Pattern.compile(
		"(?i)^(?:stat:)?([a-z][a-z0-9_-]*)(<=|>=|!=|==|=|<|>)([+-]?(?:\\d+(?:\\.\\d*)?|\\.\\d+))$");
	private static final Pattern BARE_CLAUSE = Pattern.compile(
		"(?i)^(?:stat:)?([a-z][a-z0-9_-]*)$");

	private final ItemStat stat;
	private final Operator operator;
	private final double expected;

	private StatRequirement(ItemStat stat, Operator operator, double expected)
	{
		this.stat = stat;
		this.operator = operator;
		this.expected = expected;
	}

	static StatRequirementGroup parse(String token, boolean allowBare, boolean allowPrefix)
	{
		Matcher matcher = CLAUSE.matcher(token);
		Operator operator;
		double expected;
		if (!matcher.matches())
		{
			if (!allowBare)
			{
				return null;
			}
			matcher = BARE_CLAUSE.matcher(token);
			if (!matcher.matches())
			{
				return null;
			}

			operator = Operator.GREATER_THAN;
			expected = 0.0;
		}
		else
		{
			operator = Operator.fromToken(matcher.group(2));
			try
			{
				expected = Double.parseDouble(matcher.group(3));
			}
			catch (NumberFormatException ex)
			{
				return null;
			}
			if (!Double.isFinite(expected))
			{
				return null;
			}
		}

		ItemStat stat = ItemStat.find(matcher.group(1));
		if (stat != null)
		{
			return new StatRequirementGroup(Collections.singletonList(
				new StatRequirement(stat, operator, expected)));
		}

		if (!allowPrefix)
		{
			return null;
		}

		Set<ItemStat> prefixMatches = ItemStat.findByPrefix(matcher.group(1));
		if (prefixMatches.isEmpty())
		{
			return null;
		}
		List<StatRequirement> alternatives = new ArrayList<>();
		for (ItemStat prefixMatch : prefixMatches)
		{
			alternatives.add(new StatRequirement(prefixMatch, operator, expected));
		}
		return new StatRequirementGroup(alternatives);
	}

	boolean isSatisfiedBy(ItemStats stats)
	{
		Double actual = stat.read(stats);
		return actual != null && operator.test(actual, expected);
	}

	@Override
	public boolean equals(Object other)
	{
		if (this == other)
		{
			return true;
		}
		if (!(other instanceof StatRequirement))
		{
			return false;
		}
		StatRequirement that = (StatRequirement) other;
		return stat == that.stat
			&& operator == that.operator
			&& Double.compare(expected, that.expected) == 0;
	}

	@Override
	public int hashCode()
	{
		return Objects.hash(stat, operator, expected);
	}

	private enum Operator
	{
		LESS_THAN,
		LESS_THAN_OR_EQUAL,
		EQUAL,
		NOT_EQUAL,
		GREATER_THAN_OR_EQUAL,
		GREATER_THAN;

		static Operator fromToken(String token)
		{
			switch (token)
			{
				case "<":
					return LESS_THAN;
				case "<=":
					return LESS_THAN_OR_EQUAL;
				case "=":
				case "==":
					return EQUAL;
				case "!=":
					return NOT_EQUAL;
				case ">=":
					return GREATER_THAN_OR_EQUAL;
				case ">":
					return GREATER_THAN;
				default:
					throw new IllegalArgumentException("Unknown stat comparison operator: " + token);
			}
		}

		boolean test(double actual, double expected)
		{
			int comparison = Double.compare(actual, expected);
			switch (this)
			{
				case LESS_THAN:
					return comparison < 0;
				case LESS_THAN_OR_EQUAL:
					return comparison <= 0;
				case EQUAL:
					return comparison == 0;
				case NOT_EQUAL:
					return comparison != 0;
				case GREATER_THAN_OR_EQUAL:
					return comparison >= 0;
				case GREATER_THAN:
					return comparison > 0;
				default:
					throw new IllegalStateException("Unhandled stat comparison operator: " + this);
			}
		}
	}
}

package com.betterbanksearch;

import java.util.Arrays;
import java.util.Collection;
import net.runelite.client.game.ItemStats;

final class StatRequirementGroup
{
	private final StatRequirement[] alternatives;

	StatRequirementGroup(Collection<StatRequirement> alternatives)
	{
		this.alternatives = alternatives.toArray(new StatRequirement[0]);
	}

	boolean isSatisfiedBy(ItemStats stats)
	{
		for (StatRequirement alternative : alternatives)
		{
			if (alternative.isSatisfiedBy(stats))
			{
				return true;
			}
		}
		return false;
	}

	@Override
	public boolean equals(Object other)
	{
		return this == other
			|| other instanceof StatRequirementGroup
			&& Arrays.equals(alternatives, ((StatRequirementGroup) other).alternatives);
	}

	@Override
	public int hashCode()
	{
		return Arrays.hashCode(alternatives);
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import javax.inject.Inject;

public final class TagDataLoader
{
	private static final String RESOURCE = "/com/betterbanksearch/item_tags.json";

	private final Gson gson;

	@Inject
	TagDataLoader(Gson gson)
	{
		this.gson = gson;
	}

	public TagIndex load() throws IOException
	{
		try (InputStream stream = TagDataLoader.class.getResourceAsStream(RESOURCE))
		{
			if (stream == null)
			{
				throw new IOException("Missing plugin resource: " + RESOURCE);
			}
			try (Reader reader = new InputStreamReader(stream, StandardCharsets.UTF_8))
			{
				return TagIndex.fromJson(gson, reader);
			}
		}
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.Reader;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.client.game.ItemStats;

public final class TagIndex
{
	private static final int FORMAT_VERSION = 1;
	private static final int MAX_TAGS = 128;

	private final Map<String, Integer> lookup;
	private final String[] sortedLookupKeys;
	private final Map<String, String> normalizations;
	private final Map<Integer, long[]> itemClosures;

	private TagIndex(
		Map<String, Integer> lookup,
		Map<String, String> normalizations,
		Map<Integer, long[]> itemClosures)
	{
		this.lookup = Collections.unmodifiableMap(lookup);
		this.sortedLookupKeys = lookup.keySet().toArray(new String[0]);
		Arrays.sort(sortedLookupKeys);
		this.normalizations = Collections.unmodifiableMap(normalizations);
		this.itemClosures = Collections.unmodifiableMap(itemClosures);
	}

	public static TagIndex fromJson(Gson gson, Reader reader)
	{
		TagData data = gson.fromJson(reader, TagData.class);
		if (data == null)
		{
			throw new IllegalArgumentException("Tag data is empty");
		}
		if (data.v != FORMAT_VERSION)
		{
			throw new IllegalArgumentException("Unsupported tag data version: " + data.v);
		}
		if (data.tags == null || data.tags.length == 0 || data.tags.length > MAX_TAGS)
		{
			throw new IllegalArgumentException("Tag data must contain between 1 and 128 tags");
		}

		Map<String, String> normalizations = buildNormalizations(data.norm);
		Map<String, Integer> lookup = new HashMap<>();
		Map<String, Integer> ids = new HashMap<>();

		for (int i = 0; i < data.tags.length; i++)
		{
			TagEntry tag = data.tags[i];
			if (tag == null || isBlank(tag.id) || isBlank(tag.n))
			{
				throw new IllegalArgumentException("Every tag requires an id and name");
			}
			if (ids.put(tag.id, i) != null)
			{
				throw new IllegalArgumentException("Duplicate tag id: " + tag.id);
			}

			registerLookup(lookup, canonicalizePhrase(tag.n, normalizations), i);
			if (tag.a != null)
			{
				for (String alias : tag.a)
				{
					if (isBlank(alias))
					{
						throw new IllegalArgumentException("Blank alias on tag: " + tag.id);
					}
					registerLookup(lookup, canonicalizePhrase(alias, normalizations), i);
				}
			}
		}

		validateParents(data.tags);
		long[][] ancestorBits = new long[data.tags.length][2];
		byte[] visitState = new byte[data.tags.length];
		for (int i = 0; i < data.tags.length; i++)
		{
			fillAncestors(i, data.tags, ancestorBits, visitState);
		}

		Map<Integer, long[]> itemClosures = buildItemClosures(data.items, ancestorBits);
		return new TagIndex(lookup, normalizations, itemClosures);
	}

	public boolean matches(int itemId, ParsedQuery query)
	{
		return matches(itemId, query, null);
	}

	public boolean matches(int itemId, ParsedQuery query, ItemStats stats)
	{
		return query != null && query.isSatisfiedBy(itemClosures.get(itemId), stats);
	}

	public boolean hasItem(int itemId)
	{
		return itemClosures.containsKey(itemId);
	}

	public long[] getItemClosure(int itemId)
	{
		long[] closure = itemClosures.get(itemId);
		return closure == null ? null : closure.clone();
	}

	public int itemCount()
	{
		return itemClosures.size();
	}

	Integer findTag(String normalizedNameOrAlias)
	{
		return lookup.get(normalizedNameOrAlias);
	}

	Set<Integer> findTagsByPrefix(String normalizedPrefix)
	{
		if (normalizedPrefix == null || normalizedPrefix.isEmpty())
		{
			return Collections.emptySet();
		}

		int position = Arrays.binarySearch(sortedLookupKeys, normalizedPrefix);
		if (position < 0)
		{
			position = -position - 1;
		}

		Set<Integer> matches = new LinkedHashSet<>();
		while (position < sortedLookupKeys.length
			&& sortedLookupKeys[position].startsWith(normalizedPrefix))
		{
			matches.add(lookup.get(sortedLookupKeys[position]));
			position++;
		}
		return matches;
	}

	String normalizeToken(String token)
	{
		String lower = token.toLowerCase(Locale.ROOT);
		return normalizations.getOrDefault(lower, lower);
	}

	private static Map<String, String> buildNormalizations(Map<String, String> raw)
	{
		Map<String, String> result = new HashMap<>();
		if (raw == null)
		{
			return result;
		}
		for (Map.Entry<String, String> entry : raw.entrySet())
		{
			if (isBlank(entry.getKey()) || isBlank(entry.getValue()))
			{
				throw new IllegalArgumentException("Normalizations cannot contain blank values");
			}
			String key = entry.getKey().toLowerCase(Locale.ROOT);
			String value = entry.getValue().toLowerCase(Locale.ROOT);
			if (key.indexOf(' ') >= 0 || value.indexOf(' ') >= 0)
			{
				throw new IllegalArgumentException("Normalizations must map individual tokens");
			}
			result.put(key, value);
		}
		return result;
	}

	private static String canonicalizePhrase(String phrase, Map<String, String> normalizations)
	{
		String[] tokens = phrase.trim().toLowerCase(Locale.ROOT).split("\\s+");
		StringBuilder result = new StringBuilder();
		for (String token : tokens)
		{
			if (result.length() > 0)
			{
				result.append(' ');
			}
			result.append(normalizations.getOrDefault(token, token));
		}
		return result.toString();
	}

	private static void registerLookup(Map<String, Integer> lookup, String phrase, int tagIndex)
	{
		Integer previous = lookup.putIfAbsent(phrase, tagIndex);
		if (previous != null && previous != tagIndex)
		{
			throw new IllegalArgumentException("Tag name or alias collision after normalization: " + phrase);
		}
	}

	private static void validateParents(TagEntry[] tags)
	{
		for (int i = 0; i < tags.length; i++)
		{
			int[] parents = tags[i].p;
			if (parents == null)
			{
				continue;
			}
			for (int parent : parents)
			{
				if (parent < 0 || parent >= tags.length)
				{
					throw new IllegalArgumentException("Invalid parent index on tag: " + tags[i].id);
				}
			}
		}
	}

	private static void fillAncestors(
		int tagIndex,
		TagEntry[] tags,
		long[][] ancestorBits,
		byte[] visitState)
	{
		if (visitState[tagIndex] == 2)
		{
			return;
		}
		if (visitState[tagIndex] == 1)
		{
			throw new IllegalArgumentException("Tag taxonomy contains a cycle at: " + tags[tagIndex].id);
		}

		visitState[tagIndex] = 1;
		ancestorBits[tagIndex][tagIndex >>> 6] |= 1L << (tagIndex & 63);
		if (tags[tagIndex].p != null)
		{
			for (int parent : tags[tagIndex].p)
			{
				fillAncestors(parent, tags, ancestorBits, visitState);
				ancestorBits[tagIndex][0] |= ancestorBits[parent][0];
				ancestorBits[tagIndex][1] |= ancestorBits[parent][1];
			}
		}
		visitState[tagIndex] = 2;
	}

	private static Map<Integer, long[]> buildItemClosures(
		Map<String, int[]> items,
		long[][] ancestorBits)
	{
		Map<Integer, long[]> result = new LinkedHashMap<>();
		if (items == null)
		{
			return result;
		}

		for (Map.Entry<String, int[]> entry : items.entrySet())
		{
			final int itemId;
			try
			{
				itemId = Integer.parseInt(entry.getKey());
			}
			catch (NumberFormatException ex)
			{
				throw new IllegalArgumentException("Invalid item id: " + entry.getKey(), ex);
			}
			if (itemId < 0 || result.containsKey(itemId))
			{
				throw new IllegalArgumentException("Invalid or duplicate item id: " + itemId);
			}

			long[] closure = new long[2];
			int[] itemTags = entry.getValue();
			if (itemTags == null || itemTags.length == 0)
			{
				throw new IllegalArgumentException("Item has no tags: " + itemId);
			}
			for (int tagIndex : itemTags)
			{
				if (tagIndex < 0 || tagIndex >= ancestorBits.length)
				{
					throw new IllegalArgumentException("Invalid tag index on item: " + itemId);
				}
				closure[0] |= ancestorBits[tagIndex][0];
				closure[1] |= ancestorBits[tagIndex][1];
			}
			result.put(itemId, closure);
		}
		return result;
	}

	private static boolean isBlank(String value)
	{
		return value == null || value.trim().isEmpty();
	}

	private static final class TagData
	{
		private int v;
		private TagEntry[] tags;
		private Map<String, String> norm;
		private Map<String, int[]> items;
	}

	private static final class TagEntry
	{
		private String id;
		private String n;
		private int[] p;
		private String[] a;
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.StringReader;
import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class BetterBankSearchPluginTest
{
	private TagIndex index;

	@Before
	public void setUp()
	{
		String json = "{\"v\":1,\"tags\":["
			+ "{\"id\":\"armour\",\"n\":\"Armour\",\"p\":[],\"a\":[]},"
			+ "{\"id\":\"food\",\"n\":\"Food\",\"p\":[],\"a\":[]},"
			+ "{\"id\":\"teleport\",\"n\":\"Teleport\",\"p\":[],\"a\":[]},"
			+ "{\"id\":\"teleport-jewellery\",\"n\":\"Teleport jewellery\",\"p\":[2],\"a\":[]}"
