	}

	@Test
	public void stripsSemanticPrefixesCaseInsensitively()
	{
		ParsedQuery sem = BetterBankSearchPlugin.parseSearch(index, "sem:armo", 10);
		ParsedQuery shortPrefix = BetterBankSearchPlugin.parseSearch(index, "s:armo", 10);
		ParsedQuery upperCase = BetterBankSearchPlugin.parseSearch(index, "SEM:armo", 10);

		assertNotNull(sem);
		assertEquals(sem, shortPrefix);
		assertEquals(sem, upperCase);
		assertTrue(index.matches(1, sem));
		assertFalse(index.matches(2, sem));
	}

	@Test
	public void semanticPrefixBypassesMinimumQueryLength()
	{
		assertNull(BetterBankSearchPlugin.parseSearch(index, "armour", 10));
		assertNotNull(BetterBankSearchPlugin.parseSearch(index, "s:ar", 10));
	}

	@Test
	public void bankTagQueriesAreStillIgnored()
	{
		assertNull(BetterBankSearchPlugin.parseSearch(index, "tag:armour", 1));
		assertNull(BetterBankSearchPlugin.parseSearch(index, "TAG:armour", 1));
	}

	@Test
	public void statPrefixIsParsedAndBypassesMinimumQueryLength()
