		assertNotNull(query);
		assertTrue(index.matches(3, query));
		assertFalse(index.matches(4, query));
	}

	@Test
	public void cachedQueryIsReparsedWhenMinimumLengthChanges()
	{
		BetterBankSearchPlugin plugin = new BetterBankSearchPlugin();

		assertNotNull(plugin.getCachedQuery(index, "armour", 3));
		assertNull(plugin.getCachedQuery(index, "armour", 10));
		assertNotNull(plugin.getCachedQuery(index, "armour", 3));
	}

	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(BetterBankSearchPlugin.class);
		RuneLite.main(args);
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.StringReader;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class QueryMatcherTest
{
	private TagIndex index;
	private QueryMatcher matcher;

	@Before
	public void setUp()
	{
		String json = "{\n"
			+ "  \"v\":1,\n"
			+ "  \"tags\":[\n"
			+ "    {\"id\":\"weapon\",\"n\":\"Weapon\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"magic\",\"n\":\"Magic\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"magic-weapon\",\"n\":\"Magic weapon\",\"p\":[0,1],\"a\":[]},\n"
			+ "    {\"id\":\"armour\",\"n\":\"Armour\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"ranged\",\"n\":\"Ranged\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"ranged-armour\",\"n\":\"Ranged armour\",\"p\":[3,4],\"a\":[]},\n"
			+ "    {\"id\":\"food\",\"n\":\"Food\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"potion\",\"n\":\"Potion\",\"p\":[],\"a\":[\"pots\"]},\n"
			+ "    {\"id\":\"teleport\",\"n\":\"Teleport\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"teleport-jewellery\",\"n\":\"Teleport jewellery\",\"p\":[8],\"a\":[]}\n"
			+ "  ],\n"
			+ "  \"norm\":{\"range\":\"ranged\",\"armor\":\"armour\"},\n"
			+ "  \"items\":{\n"
			+ "    \"1\":[2],\n"
			+ "    \"2\":[0,1],\n"
			+ "    \"3\":[5],\n"
			+ "    \"4\":[6],\n"
			+ "    \"5\":[7],\n"
			+ "    \"6\":[6,7],\n"
			+ "    \"7\":[4],\n"
			+ "    \"8\":[3],\n"
			+ "    \"9\":[9],\n"
			+ "    \"10\":[8]\n"
			+ "  }\n"
			+ "}";
		index = TagIndex.fromJson(new Gson(), new StringReader(json));
		matcher = new QueryMatcher(index);
	}

	@Test
	public void longestPhraseBeatsIndividualTokens()
	{
		ParsedQuery query = matcher.parse("magic weapon");

		assertEquals(1, query.requiredTagCount());
		assertTrue(index.matches(1, query));
		assertFalse(index.matches(2, query));
	}

	@Test
	public void normalizesEveryQueryToken()
	{
		ParsedQuery normalized = matcher.parse("ranged armour");
		ParsedQuery colloquial = matcher.parse("RANGE ARMOR");

		assertEquals(normalized, colloquial);
		assertTrue(index.matches(3, colloquial));
	}

	@Test
	public void requiresAllMatchedTags()
	{
		ParsedQuery query = matcher.parse("food pots");

		assertFalse(index.matches(4, query));
		assertFalse(index.matches(5, query));
		assertTrue(index.matches(6, query));
	}

	@Test
	public void rejectsEntireQueryWhenAnyPositionIsUnknown()
	{
		assertNull(matcher.parse("food definitely-unknown"));
		assertNull(matcher.parse("definitely-unknown food"));
	}

	@Test
	public void trailingPrefixMatchesTagNameWithoutApplyingTokenNormalization()
	{
		ParsedQuery fourLetters = matcher.parse("armo", true);
		ParsedQuery threeLetters = matcher.parse("arm", true);

		assertTrue(index.matches(8, fourLetters));
		assertTrue(index.matches(8, threeLetters));
	}

	@Test
	public void trailingPrefixCandidatesAreAnOrGroup()
	{
		ParsedQuery query = matcher.parse("ra", true);

		assertEquals(1, query.requiredTagCount());
		assertTrue(index.matches(7, query));
		assertTrue(index.matches(3, query));
		assertFalse(index.matches(8, query));
	}

	@Test
	public void exactGroupsAndTrailingPrefixGroupAreAllRequired()
	{
		ParsedQuery query = matcher.parse("food po", true);

		assertEquals(2, query.requiredTagCount());
		assertFalse(index.matches(4, query));
		assertFalse(index.matches(5, query));
		assertTrue(index.matches(6, query));
	}

	@Test
	public void incompleteNonTrailingTokenStillRejectsEntireQuery()
	{
		assertNull(matcher.parse("fo pots", true));
	}

	@Test
	public void unprefixedQueriesRemainExactOnly()
	{
		assertNull(matcher.parse("armo"));
	}

	@Test
	public void emptyPrefixQueryIsRejected()
	{
		assertNull(matcher.parse("", true));
		assertNull(matcher.parse("   ", true));
	}

	@Test
	public void multiWordTrailingPrefixMatches()
	{
		ParsedQuery query = matcher.parse("ranged armo", true);

		assertTrue(index.matches(3, query));
		assertFalse(index.matches(7, query));
		assertFalse(index.matches(8, query));
	}

	@Test
	public void multiWordPrefixBeatsShorterExactTag()
	{
		ParsedQuery query = matcher.parse("teleport jew", true);

		assertEquals(1, query.requiredTagCount());
		assertTrue(index.matches(9, query));
		assertFalse(index.matches(10, query));
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.StringReader;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemStats;
import org.junit.Before;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

public class StatQueryTest
{
	private TagIndex index;
	private QueryMatcher matcher;
	private ItemStats stats;

	@Before
	public void setUp()
	{
		String json = "{\"v\":1,\"tags\":["
			+ "{\"id\":\"weapon\",\"n\":\"Weapon\",\"p\":[],\"a\":[]},"
			+ "{\"id\":\"magic\",\"n\":\"Magic\",\"p\":[],\"a\":[]},"
			+ "{\"id\":\"magic-weapon\",\"n\":\"Magic weapon\",\"p\":[0,1],\"a\":[]},"
			+ "{\"id\":\"armour\",\"n\":\"Armour\",\"p\":[],\"a\":[]}"
			+ "],\"norm\":{},\"items\":{\"1\":[2],\"2\":[0],\"3\":[3]}}";
		index = TagIndex.fromJson(new Gson(), new StringReader(json));
		matcher = new QueryMatcher(index);

		ItemEquipmentStats equipment = ItemEquipmentStats.builder()
			.astab(1)
			.aslash(2)
			.acrush(3)
			.amagic(4)
			.arange(5)
			.dstab(6)
			.dslash(7)
			.dcrush(8)
			.dmagic(9)
			.drange(10)
			.str(11)
			.rstr(12)
			.mdmg(13.5f)
			.prayer(14)
			.aspeed(4)
			.build();
		stats = new ItemStats(true, 15.25, 16, equipment);
	}

	@Test
	public void supportsAllMajorNumericStats()
	{
		String[] clauses = {
			"attack-stab=1",
			"attack-slash=2",
			"attack-crush=3",
			"attack-magic=4",
			"attack-ranged=5",
			"defence-stab=6",
			"defence-slash=7",
			"defence-crush=8",
			"defence-magic=9",
			"defence-ranged=10",
			"strength=11",
			"ranged-strength=12",
			"magic-damage=13.5",
			"prayer=14",
			"attack-speed=4",
			"weight=15.25",
			"ge-limit=16"
		};

		for (String clause : clauses)
		{
			ParsedQuery query = matcher.parse("stat:" + clause);
			assertEquals(clause, 1, query.requiredStatCount());
			assertTrue(clause, index.matches(999, query, stats));
		}
	}

	@Test
	public void acceptsPrefixedAndUnprefixedAliases()
	{
		assertTrue(index.matches(999, matcher.parse("str>=11"), stats));
		assertTrue(index.matches(999, matcher.parse("STAT:melee_strength>=11"), stats));
		assertTrue(index.matches(999, matcher.parse("stat: strength>=11"), stats));
		assertTrue(index.matches(999, matcher.parse("stab-defense=6"), stats));
		assertTrue(index.matches(999, matcher.parse("range-attack=5"), stats));
	}

	@Test
	public void bareStatsDefaultToPositiveWithoutTakingOverExistingTags()
	{
		assertTrue(index.matches(999, matcher.parse("strength"), stats));
		assertTrue(index.matches(999, matcher.parse("stat:strength"), stats));

		ParsedQuery magicTag = matcher.parse("magic");
		assertEquals(1, magicTag.requiredTagCount());
		assertEquals(0, magicTag.requiredStatCount());
		assertTrue(index.matches(1, magicTag));

		ParsedQuery magicStat = matcher.parse("stat:magic");
		assertEquals(0, magicStat.requiredTagCount());
		assertEquals(1, magicStat.requiredStatCount());
		assertTrue(index.matches(999, magicStat, stats));
		assertFalse(index.matches(999, matcher.parse("stat:strength"),
			new ItemStats(true, 1.0, 1, ItemEquipmentStats.builder().str(0).build())));
	}

	@Test
	public void explicitStatPrefixCompletesPartialNamesExactFirst()
	{
		assertTrue(index.matches(999, matcher.parse("stat:stren"), stats));
		assertTrue(index.matches(999, matcher.parse("stat:magic-d>13"), stats));
		assertTrue(index.matches(999, matcher.parse("stat:defence>9"), stats));
		assertFalse(index.matches(999, matcher.parse("stat:defence>10"), stats));

		// The exact ranged alias resolves to ranged attack (5), rather than the
		// ranged-strength prefix candidate (12).
		assertFalse(index.matches(999, matcher.parse("stat:ranged>5"), stats));
		assertNull(matcher.parse("stren"));
	}

	@Test
	public void supportsEveryComparisonOperator()
	{
		assertTrue(index.matches(999, matcher.parse("strength>10"), stats));
		assertTrue(index.matches(999, matcher.parse("strength>=11"), stats));
		assertTrue(index.matches(999, matcher.parse("strength=11"), stats));
		assertTrue(index.matches(999, matcher.parse("strength==11"), stats));
		assertTrue(index.matches(999, matcher.parse("strength!=12"), stats));
		assertTrue(index.matches(999, matcher.parse("strength<=11"), stats));
		assertTrue(index.matches(999, matcher.parse("strength<12"), stats));
		assertFalse(index.matches(999, matcher.parse("strength>11"), stats));
	}

	@Test
	public void combinesTagsAndMultipleStatRequirements()
	{
		ParsedQuery query = matcher.parse("magic weapon stat:strength>=10 prayer>10");

		assertEquals(1, query.requiredTagCount());
		assertEquals(2, query.requiredStatCount());
		assertTrue(index.matches(1, query, stats));
		assertFalse(index.matches(2, query, stats));
		assertFalse(index.matches(1, query, new ItemStats(true, 15.25, 16, null)));
	}

	@Test
	public void statOnlyQueriesDoNotRequireSemanticTags()
	{
		assertTrue(index.matches(999, matcher.parse("weight<20"), stats));
	}

	@Test
	public void missingStatsDoNotBehaveLikeZero()
	{
		assertFalse(index.matches(999, matcher.parse("strength=0"), null));
		assertFalse(index.matches(999, matcher.parse("strength=0"),
			new ItemStats(false, 1.0, 0, null)));
	}

	@Test
	public void rejectsUnknownOrMalformedExplicitStatClauses()
	{
		assertNull(matcher.parse("stat:definitely-unknown>1"));
		assertNull(matcher.parse("stat:strength>"));
		assertNull(matcher.parse("stat:"));
	}

	@Test
	public void trailingTagAutocompleteStillWorksAfterAStatClause()
	{
		ParsedQuery query = matcher.parse("stat:weight<20 armo", true);

		assertTrue(index.matches(3, query, stats));
		assertFalse(index.matches(1, query, stats));
	}
}

package com.betterbanksearch;

import com.google.gson.Gson;
import java.io.StringReader;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

public class TagIndexTest
{
	@Test
	public void computesClosuresAcrossMultipleParents()
	{
		TagIndex index = index("{\n"
			+ "  \"v\":1,\n"
			+ "  \"tags\":[\n"
			+ "    {\"id\":\"equipment\",\"n\":\"Equipment\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"armour\",\"n\":\"Armour\",\"p\":[0],\"a\":[]},\n"
			+ "    {\"id\":\"ranged\",\"n\":\"Ranged\",\"p\":[],\"a\":[]},\n"
			+ "    {\"id\":\"ranged-armour\",\"n\":\"Ranged armour\",\"p\":[1,2],\"a\":[]},\n"
			+ "    {\"id\":\"body-slot\",\"n\":\"Body\",\"p\":[0],\"a\":[]}\n"
			+ "  ],\n"
			+ "  \"norm\":{},\n"
			+ "  \"items\":{\"100\":[3,4]}\n"
			+ "}");

		QueryMatcher matcher = new QueryMatcher(index);
		assertTrue(index.matches(100, matcher.parse("equipment")));
		assertTrue(index.matches(100, matcher.parse("armour")));
		assertTrue(index.matches(100, matcher.parse("ranged")));
		assertTrue(index.matches(100, matcher.parse("body")));
