	@Test
	public void bundledArtifactLoadsAndMatchesGoldenItems()
		throws Exception
	{
		TagIndex index = new TagDataLoader(new Gson()).load();
		QueryMatcher matcher = new QueryMatcher(index);

		// The artifact is pipeline-generated; its exact size changes with game
		// updates, so assert semantic invariants instead of a count.
		assertTrue(index.itemCount() >= 1000);
		assertTrue(index.matches(379, matcher.parse("food"))); // Lobster
		assertTrue(index.matches(385, matcher.parse("food"))); // Shark
		assertTrue(index.matches(377, matcher.parse("raw food")));
		assertFalse(index.matches(379, matcher.parse("raw food")));
		assertTrue(index.matches(1135, matcher.parse("range armor")));
		assertNotNull(index.getItemClosure(1135));
	}

	private static TagIndex index(String json)
	{
		return TagIndex.fromJson(new Gson(), new StringReader(json));
	}
